# region: fold
def fold(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs, floor_=2):
    return [v for v in xs if v > floor_]

# region: sift
def sift(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: digest
def digest(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: emit
def emit(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return emit(digest(sift(intake(fold(raw)))))

